// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.JobObservation) predicate.JobObservation {
	return predicate.JobObservation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.JobObservation) predicate.JobObservation {
	return predicate.JobObservation(sql.NotPredicates(p))
}
